const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define locations
  const mountIsa = ee.Geometry.Point([139.49, -20.73]);
  const townsville = ee.Geometry.Point([146.82, -19.26]);

  // Create regions around each point (10km buffer)
  const mountIsaRegion = mountIsa.buffer(10000);
  const townsvilleRegion = townsville.buffer(10000);

  // Date range
  const startDate = '2019-01-27';
  const endDate = '2019-02-11'; // Inclusive of Feb 10

  // Get GPM precipitation data
  const gpm = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(startDate, endDate)
    .select('precipitationCal');

  const collectionSize = gpm.size().getInfo();
  console.log('Collection size:', collectionSize);

  if (collectionSize === 0) {
    console.log('No precipitation data found for the date range.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Sum precipitation over the period (mm/hr * 0.5hr intervals)
  // GPM data is at 30-minute intervals
  const totalPrecip = gpm.sum().multiply(0.5);

  // Calculate for Mount Isa
  const mountIsaStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: mountIsaRegion,
    scale: 10000,
    maxPixels: 1e9
  });

  const mountIsaCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: mountIsaRegion,
    scale: 10000,
    maxPixels: 1e9
  });

  const mountIsaPrecip = mountIsaStats.get('precipitationCal').getInfo();
  const mountIsaPixels = mountIsaCount.get('precipitationCal').getInfo();

  // Calculate for Townsville
  const townsvilleStats = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: townsvilleRegion,
    scale: 10000,
    maxPixels: 1e9
  });

  const townsvilleCount = totalPrecip.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: townsvilleRegion,
    scale: 10000,
    maxPixels: 1e9
  });

  const townsvillePrecip = townsvilleStats.get('precipitationCal').getInfo();
  const townsvillePixels = townsvilleCount.get('precipitationCal').getInfo();

  console.log('Mount Isa - Pixels:', mountIsaPixels, 'Precip (mm):', mountIsaPrecip ? mountIsaPrecip.toFixed(2) : 'null');
  console.log('Townsville - Pixels:', townsvillePixels, 'Precip (mm):', townsvillePrecip ? townsvillePrecip.toFixed(2) : 'null');

  if (mountIsaPixels === 0 || townsvillePixels === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (mountIsaPrecip === null || townsvillePrecip === null || 
      isNaN(mountIsaPrecip) || isNaN(townsvillePrecip)) {
    console.log('Calculation failed - null or NaN result.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert to cm (divide by 10)
  const mountIsaCm = mountIsaPrecip / 10;
  const townsvilleCm = townsvillePrecip / 10;

  console.log('Mount Isa rainfall: ' + mountIsaCm.toFixed(2) + ' cm');
  console.log('Townsville rainfall: ' + townsvilleCm.toFixed(2) + ' cm');
  console.log('Threshold: 65 cm');

  // Check if BOTH regions exceeded 65 cm
  if (mountIsaCm > 65 && townsvilleCm > 65) {
    console.log('Both regions exceeded 65 cm.');
    console.log('<answer>A</answer>');
  } else {
    console.log('At least one region did not exceed 65 cm.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
